def select_words(s, n):
    if not s:
        return []

    def count_consonants(word):
        count = 0
        for char in word:
            if char.isalpha() and char.lower() not in 'aeiou':
                count += 1
        return count

    words = s.split()
    result = [word for word in words if count_consonants(word) == n]

    return result

