    requires n >= 0
    requires s == "" || forall i: int :: 0 <= i < s.Length ==> (s[i] >= 'a' && s[i] <= 'z' || s[i] >= 'A' && s[i] <= 'Z' || s[i] == ' ')
    ensures result == [] ==> s == "" 
    ensures result.Length == 0 ==> (exists w: string :: w in result && CountConsonants(w) == n)
    ensures result.Length > 0 ==> (forall w: string :: w in result ==> CountConsonants(w) == n)

    // Helper function to count consonants
    function CountConsonants(word: string): int
        requires word != null
        ensures 0 <= CountConsonants(word) <= word.Length
    {
        var count := 0;
        var i := 0;
        while i < word.Length
            invariant 0 <= i <= word.Length
            invariant count == CountConsonants(word[0..i])
        {
            if (word[i] != 'a' && word[i] != 'e' && word[i] != 'i' && word[i] != 'o' && word[i] != 'u' &&
                word[i] != 'A' && word[i] != 'E' && word[i] != 'I' && word[i] != 'O' && word[i] != 'U' &&
                word[i] != ' ') {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }

